package com.google.javascript.jscomp;

import junit.framework.TestCase;

public class FlowSensitiveInlineVariablesAI170Test extends TestCase {

  private Compiler compiler;

  @Override
  protected void setUp() throws Exception {
    super.setUp();
    compiler = new Compiler();
  }

  private void test(String js, String expected) {
    CompilerOptions options = new CompilerOptions();
    options.flowSensitiveInlineVariables = true;
    compiler.init(
        new JSSourceFile[] {},
        new JSSourceFile[] {JSSourceFile.fromCode("test.js", js)},
        options);
    compiler.parse();
    compiler.processDefines();
    Node root = compiler.getRoot();
    new FlowSensitiveInlineVariables(compiler).process(null, root);
    String generated = compiler.toSource();
    assertEquals(expected, generated);
  }

  public void testInlineSimpleVariable() {
    test("function f() { var x = 1; return x; }", "function f() {return 1;}");
  }

  public void testNoInlineMultipleUses() {
    String js = "function f() { var x = 1; return x + x; }";
    test(js, js);
  }
}
